
#' Generate framework-derived cluster annotations
#'
#' Converts multidimensional Framework scores into a concise,
#' human-readable annotation for each analyzed macrophage cluster.
#'
#' Identity is intentionally excluded here. Macrophage identity is
#' established upstream by the independent macrophage detector.
#'
#' The final annotation includes only the dominant Lineage program
#' and the primary Functional State program. Secondary functional
#' programs remain available in the multidimensional profile outputs.
#'
#' @param profile A cluster profile generated by analyze_macrophage_profile().
#' @param ontology Macrophage ontology data frame.
#'
#' @return A data frame containing Cluster, Lineage,
#' Functional_State_1 and Full_annotation.
#' @keywords internal

.generate_framework_annotations <- function(profile, ontology) {
  
  if (!is.list(profile) || is.null(profile$scores)) {
    stop("profile must contain a 'scores' matrix.")
  }
  
  if (!is.data.frame(ontology)) {
    stop("ontology must be a data frame.")
  }
  
  scores <- profile$scores
  
  lineage_programs <- unique(
    ontology$Program[ontology$Dimension == "Lineage"]
  )
  
  functional_programs <- unique(
    ontology$Program[ontology$Dimension == "Functional State"]
  )
  
  if (length(lineage_programs) == 0) {
    stop("Ontology must contain Lineage programs.")
  }
  
  if (length(functional_programs) == 0) {
    stop("Ontology must contain Functional State programs.")
  }
  
  clusters <- colnames(scores)
  
  annotations <- lapply(clusters, function(cluster) {
    
    cluster_scores <- scores[, cluster]
    
    # --------------------------------------------------
    # Dominant Lineage
    # --------------------------------------------------
    
    lineage_scores <- cluster_scores[
      intersect(lineage_programs, names(cluster_scores))
    ]
    
    if (length(lineage_scores) == 0) {
      lineage <- NA_character_
    } else {
      lineage <- names(lineage_scores)[
        which.max(lineage_scores)
      ]
    }
    
    # --------------------------------------------------
    # Primary Functional State
    # --------------------------------------------------
    
    functional_scores <- cluster_scores[
      intersect(functional_programs, names(cluster_scores))
    ]
    
    if (length(functional_scores) == 0) {
      functional_1 <- NA_character_
    } else {
      functional_1 <- names(functional_scores)[
        which.max(functional_scores)
      ]
    }
    
    # --------------------------------------------------
    # Final annotation: Lineage + primary state only
    # --------------------------------------------------
    
    components <- c(
      lineage,
      functional_1
    )
    
    components <- components[
      !is.na(components) & nzchar(components)
    ]
    
    full_annotation <- paste(
      components,
      collapse = " | "
    )
    
    data.frame(
      Cluster = cluster,
      Lineage = lineage,
      Functional_State_1 = functional_1,
      Full_annotation = full_annotation,
      stringsAsFactors = FALSE
    )
  })
  
  annotations <- do.call(rbind, annotations)
  
  rownames(annotations) <- NULL
  
  annotations$Cluster <- factor(
    annotations$Cluster,
    levels = clusters
  )
  
  annotations <- annotations[
    order(annotations$Cluster),
    ,
    drop = FALSE
  ]
  
  annotations$Cluster <- as.character(
    annotations$Cluster
  )
  
  rownames(annotations) <- NULL
  
  return(annotations)
}
